const maxPhotosPerReport = 5;
function configurePhotoPicker(inputId, getPhotos, setPhotos, refresh) {
  q(inputId).onchange = async () => {
    const input = q(inputId), current = getPhotos(), available = maxPhotosPerReport - current.length;
    if (available <= 0) { input.value = ''; alert('Aquest informe ja té el màxim de 5 fotos.'); return; }
    const selected = [...input.files], files = selected.slice(0, available);
    if (selected.length > available) alert(`Només s’afegiran ${available} foto${available === 1 ? '' : 's'}: el màxim per informe és de 5.`);
    const photos = await Promise.all(files.map(compactPhoto));
    setPhotos([...current, ...photos]);
    input.value = '';
    refresh();
  };
}
